:root{--film-selection:rgba(61,154,209,0.28);--film-thumb:rgba(100,113,127,0.32);--film-thumb-hover:rgba(100,113,127,0.55);--film-stroke:1.75;--film-tint:rgba(166,216,242,0.14);--film-r-sm:8px;--film-r:14px;--film-r-lg:18px;--film-line:linear-gradient(90deg,transparent,rgba(61,154,209,0.5) 18%,rgba(166,216,242,0.62) 50%,rgba(61,154,209,0.5) 82%,transparent);--film-rim:rgba(100,113,127,0.3);--film-rim-strong:rgba(100,113,127,0.42);--film-sheen:rgba(255,255,255,0.8);--film-lift:0 1px 2px rgba(28,39,51,0.06),0 6px 18px -10px rgba(28,39,51,0.16);--film-shadow:0 1px 2px rgba(28,39,51,0.05),0 12px 32px -16px rgba(28,39,51,0.22);--film-shadow-deep:0 2px 6px rgba(28,39,51,0.06),0 24px 56px -20px rgba(28,39,51,0.28);--film-focus:rgba(61,154,209,0.7);--film-ring:rgba(61,154,209,0.26);--film-link-line:rgba(61,154,209,0.5);--film-frost:rgba(255,255,255,0.9)}
::selection{background:var(--film-selection)}
::-webkit-scrollbar{width:10px;height:10px;background:transparent}
::-webkit-scrollbar-thumb{background:var(--film-thumb);border:3px solid transparent;border-radius:99px;background-clip:padding-box}
::-webkit-scrollbar-thumb:hover{background-color:var(--film-thumb-hover)}
[data-slot="scroll-area-thumb"]{background:var(--film-thumb)!important}
svg.lucide{stroke-width:var(--film-stroke)}
[data-slot="sidebar-inner"]{background-image:linear-gradient(180deg,var(--film-tint),transparent 42%)}
[data-thread-item]{border-radius:var(--film-r-sm)}
[data-chat-header]{background-image:var(--film-line);background-size:100% 1px;background-position:bottom;background-repeat:no-repeat}
[data-user-message-bubble]{border:1px solid var(--film-rim);border-radius:var(--film-r)!important;box-shadow:var(--film-lift)}
.chat-markdown-codeblock{border:1px solid var(--film-rim);border-radius:var(--film-r-sm);box-shadow:inset 0 1px 0 var(--film-sheen)}
.chat-markdown a{text-decoration-color:var(--film-link-line);text-underline-offset:3px}
[data-thread-details-card]{border:1px solid var(--film-rim);border-radius:var(--film-r)!important;box-shadow:var(--film-lift)}
[data-slot="composer-host"]{border-color:var(--film-rim-strong)!important;border-radius:var(--film-r-lg)!important;box-shadow:var(--film-shadow);transition:border-color .16s ease-out,box-shadow .16s ease-out}
[data-slot="composer-host"]:focus-within{border-color:var(--film-focus)!important;box-shadow:var(--film-shadow),0 0 0 3px var(--film-ring)}
[data-slot="input"],[data-slot="select-trigger"]{border-radius:var(--film-r-sm)}
[data-slot="input"]:focus-visible,[data-slot="select-trigger"]:focus-visible,[data-slot="button"]:focus-visible{outline:none;box-shadow:0 0 0 3px var(--film-ring)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{background-color:var(--film-frost)!important;-webkit-backdrop-filter:blur(16px) saturate(1.15);backdrop-filter:blur(16px) saturate(1.15);border:1px solid var(--film-rim-strong)!important;border-radius:var(--film-r)!important;box-shadow:var(--film-shadow-deep)}
[data-slot="tooltip-popup"]{border:1px solid var(--film-rim);border-radius:var(--film-r-sm)!important;box-shadow:var(--film-shadow)}
[data-thread-terminal-drawer]{box-shadow:inset 0 1px 0 var(--film-rim)}
